  cinematicChapters: { label: 'Cinematic Chapters', description: 'Eine geführte Geschichte aus wenigen, klaren Kapiteln.', requirements: ['3–6 Kapitel', 'einheitliche Bildsprache', 'kurze Texte statt langer Absätze'] },
  transformationSequence: { label: 'Transformation Sequence', description: 'Zeigt eine nachvollziehbare Entwicklung vom Ausgangspunkt zum Ergebnis.', requirements: ['3–6 Zustände', 'gleiche Perspektive empfohlen', 'Kennzahlen nur mit belastbarer Grundlage'] },
  xrayReveal: { label: 'X-Ray Reveal', description: 'Zwei deckungsgleiche Bilder werden durch eine interaktive Linse verglichen.', requirements: ['identische Perspektive', 'identischer Zuschnitt', 'beide Bilder gleich groß exportieren'] },
  sceneLab: { label: 'Scene Lab', description: 'Ein Basisbild wird mit transparenten, deckungsgleichen Auswahl-Layern kombiniert.', requirements: ['festes Basisbild', 'transparente WebP/PNG-Layer', 'alle Layer im selben Format'] },
  infiniteCanvas: { label: 'Infinite Canvas', description: 'Eine große Bildsammlung wird zum räumlichen Fullscreen-Explorer.', requirements: ['10–40 hochwertige Bilder', 'kurze Titel und Alt-Texte', 'Links und Kategorien optional'] },
  kineticIdentity: { label: 'Kinetic Identity', description: 'Kurze Markenaussagen wechseln als typografisch choreografierte Bühne.', requirements: ['3–6 Aussagen', 'ein prägnantes Fokuswort', 'Bilder sind optional'] },
  signaturePath: { label: 'Signature Path', description: 'Ein kuratierter Pfad verbindet geordnete Stationen automatisch.', requirements: ['3–7 Stationen', 'keine SVG-Datei nötig', 'kurze, klare Texte'] },
  layeredAnatomy: { label: 'Layered Anatomy', description: 'Standard-Hotspots oder ein Pro-Aufbau aus transparenten Bildebenen.', requirements: ['Standard: ein Basisbild', 'Pro: deckungsgleiche Ebenen', 'maximal 8 Details'] },
  guidedChoice: { label: 'Guided Choice', description: 'Verständliche Fragen führen deterministisch zu einer Empfehlung.', requirements: ['2–6 Fragen', '2–4 Antworten je Frage', 'mindestens 2 Ergebnisse'] },
  dayToNight: { label: 'Day to Night', description: 'Zwei bis vier Szenen werden über eine klare Zeitachse erlebbar.', requirements: ['2–4 Szenen', 'Zeit und Stimmung benennen', 'abgestimmte Bildsprache'] },
  livingBlueprint: { label: 'Living Blueprint', description: 'Knoten und Verbindungen werden aus einer geordneten Liste erzeugt.', requirements: ['3–8 Knoten', 'keine Koordinaten nötig', 'kurze Titel und Kennzahlen'] },
