type AnatomyHotspot = { id: string; x: number; y: number; title: string; text: string; icon: string };
type AnatomyLayer = { id: string; image: string; title: string; text: string; direction: string; depth: number };
function LayeredAnatomyEditor({ data, onChange }: EditorProps) {
  const [value, setValue] = useState({ badge: String(data.badge || ''), headline: String(data.headline || ''), subline: String(data.subline || ''), mode: data.mode === 'layers' ? 'layers' : 'hotspots', baseImage: String(data.baseImage || ''), aspectRatio: String(data.aspectRatio || '4/3'), cta: (data.cta as { label: string; href: string }) || { label: '', href: '' }, hotspots: (Array.isArray(data.hotspots) ? data.hotspots as Array<Partial<AnatomyHotspot>> : []).map((item) => ({ id: item.id || makeId('hotspot'), x: Number(item.x ?? 50), y: Number(item.y ?? 50), title: item.title || '', text: item.text || '', icon: item.icon || '' })), layers: (Array.isArray(data.layers) ? data.layers as Array<Partial<AnatomyLayer>> : []).map((item) => ({ id: item.id || makeId('layer'), image: item.image || '', title: item.title || '', text: item.text || '', direction: item.direction || 'right', depth: Number(item.depth || 1) })) });
  useReport(value, onChange);
  const updateHotspot = (index: number, patch: Partial<AnatomyHotspot>) => setValue((current) => ({ ...current, hotspots: current.hotspots.map((item, itemIndex) => itemIndex === index ? { ...item, ...patch } : item) }));
  const updateLayer = (index: number, patch: Partial<AnatomyLayer>) => setValue((current) => ({ ...current, layers: current.layers.map((item, itemIndex) => itemIndex === index ? { ...item, ...patch } : item) }));
  const count = value.mode === 'layers' ? value.layers.length : value.hotspots.length;
  return <AdvancedFrame type="layeredAnatomy" checks={[{ label: 'Überschrift gesetzt', ok: Boolean(value.headline.trim()) }, { label: 'Basisbild gesetzt', ok: Boolean(value.baseImage) }, { label: '2 bis 8 Details', ok: count >= 2 && count <= 8 }, { label: value.mode === 'layers' ? 'Alle Ebenen haben transparente Assets' : 'Alle Hotspots sind benannt', ok: value.mode === 'layers' ? value.layers.every((item) => item.image && item.title) : value.hotspots.every((item) => item.title) }]}><CommonAdvancedFields value={value} onPatch={(patch) => setValue({ ...value, ...patch })} /><EditorGroup title="2. Modus und Basis"><SelectField label="Darstellung" value={value.mode} onChange={(mode) => setValue({ ...value, mode })} options={[{ value: 'hotspots', label: 'Standard · Hotspots' }, { value: 'layers', label: 'Pro · Explodierte Ebenen' }]} /><div className={`rounded-xl border p-3 text-xs leading-5 ${value.mode === 'layers' ? 'border-amber-200 bg-amber-50 text-amber-900' : 'border-blue-200 bg-blue-50 text-blue-900'}`}>{value.mode === 'layers' ? 'Pro benötigt transparente, pixelgenau ausgerichtete PNG/WebP-Ebenen. Flamingo kann diese Assets auf Anfrage erstellen.' : 'Standard benötigt nur ein normales Bild. Positionen lassen sich über X/Y-Prozentwerte präzise setzen.'}</div><ImageUploadField label="Basisbild" value={value.baseImage} onChange={(baseImage) => setValue({ ...value, baseImage })} /><SelectField label="Bildformat" value={value.aspectRatio} onChange={(aspectRatio) => setValue({ ...value, aspectRatio })} options={[{ value: '16/9', label: '16:9' }, { value: '4/3', label: '4:3' }, { value: '1/1', label: 'Quadrat' }]} /></EditorGroup>{value.mode === 'hotspots' ? <EditorGroup title="3. Hotspots" description="X/Y sind Prozentwerte im Bild. 50/50 liegt exakt in der Mitte.">{value.hotspots.map((item, index) => <ItemPanel key={item.id} label={`${index + 1} · ${item.title || 'Neuer Hotspot'}`}><div className="mb-3 flex justify-end"><ReorderButtons index={index} length={value.hotspots.length} onMove={(from, to) => setValue({ ...value, hotspots: moveItem(value.hotspots, from, to) })} onRemove={() => setValue({ ...value, hotspots: value.hotspots.filter((_, itemIndex) => itemIndex !== index) })} /></div><div className="grid gap-3 sm:grid-cols-2"><TextField label="Titel" value={item.title} onChange={(title) => updateHotspot(index, { title })} /><div className="grid grid-cols-2 gap-2"><TextField label="X (0–100)" value={String(item.x)} onChange={(x) => updateHotspot(index, { x: Math.min(100, Math.max(0, Number(x) || 0)) })} /><TextField label="Y (0–100)" value={String(item.y)} onChange={(y) => updateHotspot(index, { y: Math.min(100, Math.max(0, Number(y) || 0)) })} /></div></div><div className="mt-3"><TextField label="Erklärung" value={item.text} onChange={(text) => updateHotspot(index, { text })} multiline /></div></ItemPanel>)}<button type="button" disabled={value.hotspots.length >= 8} onClick={() => setValue({ ...value, hotspots: [...value.hotspots, { id: makeId('hotspot'), x: 50, y: 50, title: '', text: '', icon: '' }] })} className="text-sm font-semibold text-violet-700 disabled:opacity-40">+ Hotspot hinzufügen</button></EditorGroup> : <EditorGroup title="3. Pro-Ebenen" description="Bulk-Upload übernimmt die Dateinamen als vorläufige Titel."><BulkImageActions label="Transparente Ebenen hochladen" onSelect={(images) => setValue((current) => ({ ...current, layers: [...current.layers, ...images.map((image, index) => ({ id: makeId('layer'), image: image.src, title: image.alt, text: '', direction: index % 2 ? 'right' : 'left', depth: index + 1 }))].slice(0, 8) }))} />{value.layers.map((item, index) => <ItemPanel key={item.id} image={item.image} label={`${index + 1} · ${item.title || 'Neue Ebene'}`}><div className="mb-3 flex justify-end"><ReorderButtons index={index} length={value.layers.length} onMove={(from, to) => setValue({ ...value, layers: moveItem(value.layers, from, to) })} onRemove={() => setValue({ ...value, layers: value.layers.filter((_, itemIndex) => itemIndex !== index) })} /></div><ImageUploadField label="Transparente Ebene" value={item.image} onChange={(image) => updateLayer(index, { image })} /><div className="mt-3 grid gap-3 sm:grid-cols-2"><TextField label="Titel" value={item.title} onChange={(title) => updateLayer(index, { title })} /><SelectField label="Explosionsrichtung" value={item.direction} onChange={(direction) => updateLayer(index, { direction })} options={[{ value: 'left', label: 'Links' }, { value: 'right', label: 'Rechts' }, { value: 'up', label: 'Oben' }, { value: 'down', label: 'Unten' }]} /></div><div className="mt-3"><TextField label="Erklärung" value={item.text} onChange={(text) => updateLayer(index, { text })} multiline /></div></ItemPanel>)}</EditorGroup>}<EditorGroup title="4. Abschluss"><ButtonField label="Button (optional)" value={value.cta} onChange={(cta) => setValue({ ...value, cta })} /></EditorGroup></AdvancedFrame>;
}

type ChoiceScore = { resultId: string; points: number };
type ChoiceAnswer = { id: string; label: string; description: string; scores: ChoiceScore[]; nextQuestionId: string; resultId: string };
type ChoiceQuestion = { id: string; label: string; description: string; answers: ChoiceAnswer[] };
type ChoiceResult = { id: string; title: string; text: string; image: string; features: string[]; cta: { label: string; href: string } };

function GuidedChoiceTest({ mode, questions, results }: { mode: string; questions: ChoiceQuestion[]; results: ChoiceResult[] }) {
  const [currentId, setCurrentId] = useState(questions[0]?.id || '');
  const [scores, setScores] = useState<Record<string, number>>({});
  const [resultId, setResultId] = useState('');
  const [steps, setSteps] = useState(0);
  const current = questions.find((question) => question.id === currentId) || questions[0];
  const result = results.find((entry) => entry.id === resultId);
  function reset() { setCurrentId(questions[0]?.id || ''); setScores({}); setResultId(''); setSteps(0); }
  function choose(answer: ChoiceAnswer) {
    if (mode === 'branch') { if (answer.resultId) setResultId(answer.resultId); else if (answer.nextQuestionId) setCurrentId(answer.nextQuestionId); return; }
    const nextScores = { ...scores }; answer.scores.forEach((score) => { nextScores[score.resultId] = (nextScores[score.resultId] || 0) + Number(score.points || 0); }); setScores(nextScores);
    const next = questions[steps + 1]; if (next) { setCurrentId(next.id); setSteps(steps + 1); } else { const winner = results.map((entry, index) => ({ id: entry.id, score: nextScores[entry.id] || 0, index })).sort((a, b) => b.score - a.score || a.index - b.index)[0]; setResultId(winner?.id || ''); }
  }
  return <div className="rounded-xl border border-violet-200 bg-violet-50/60 p-4"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-bold text-violet-950">Testlauf</p><p className="text-[11px] text-violet-700">Prüfe den Ablauf ohne die Seite zu verlassen.</p></div><button type="button" onClick={reset} className="rounded-lg border border-violet-200 bg-white px-3 py-2 text-xs font-bold text-violet-700">Neu starten</button></div>{result ? <div className="mt-4 rounded-lg bg-white p-4"><p className="text-[10px] font-bold uppercase tracking-wider text-emerald-600">Ergebnis erreicht</p><p className="mt-1 text-sm font-bold text-zinc-900">{result.title}</p></div> : current ? <div className="mt-4"><p className="text-sm font-bold text-zinc-900">{current.label}</p><div className="mt-2 flex flex-wrap gap-2">{current.answers.map((answer) => <button key={answer.id} type="button" onClick={() => choose(answer)} className="rounded-lg border border-zinc-200 bg-white px-3 py-2 text-xs font-semibold text-zinc-800 hover:border-violet-400">{answer.label || 'Unbenannte Antwort'}</button>)}</div></div> : <p className="mt-4 text-xs text-red-700">Keine gültige Startfrage vorhanden.</p>}</div>;
}

function GuidedChoiceEditor({ data, onChange }: EditorProps) {
  const resultInput = Array.isArray(data.results) ? data.results as Array<Partial<ChoiceResult>> : [];
  const questionInput = Array.isArray(data.questions) ? data.questions as Array<Partial<ChoiceQuestion>> : [];
  const [value, setValue] = useState({ badge: String(data.badge || ''), headline: String(data.headline || ''), subline: String(data.subline || ''), mode: data.mode === 'branch' ? 'branch' : 'score', restartLabel: String(data.restartLabel || 'Neu starten'), results: resultInput.map((item) => ({ id: item.id || makeId('result'), title: item.title || '', text: item.text || '', image: item.image || '', features: Array.isArray(item.features) ? item.features.map(String) : [], cta: item.cta || { label: '', href: '' } })), questions: questionInput.map((item) => ({ id: item.id || makeId('question'), label: item.label || '', description: item.description || '', answers: (Array.isArray(item.answers) ? item.answers : []).map((answer) => ({ id: answer.id || makeId('answer'), label: answer.label || '', description: answer.description || '', scores: Array.isArray(answer.scores) ? answer.scores.map((score) => ({ resultId: score.resultId || '', points: Number(score.points || 0) })) : [], nextQuestionId: answer.nextQuestionId || '', resultId: answer.resultId || '' })) })) });
  useReport(value, onChange);
  const updateQuestion = (index: number, patch: Partial<ChoiceQuestion>) => setValue((current) => ({ ...current, questions: current.questions.map((item, itemIndex) => itemIndex === index ? { ...item, ...patch } : item) }));
  const updateAnswer = (questionIndex: number, answerIndex: number, patch: Partial<ChoiceAnswer>) => setValue((current) => ({ ...current, questions: current.questions.map((question, index) => index === questionIndex ? { ...question, answers: question.answers.map((answer, nestedIndex) => nestedIndex === answerIndex ? { ...answer, ...patch } : answer) } : question) }));
  const updateResult = (index: number, patch: Partial<ChoiceResult>) => setValue((current) => ({ ...current, results: current.results.map((item, itemIndex) => itemIndex === index ? { ...item, ...patch } : item) }));
  const validAnswers = value.questions.every((question) => question.label && question.answers.length >= 2 && question.answers.length <= 4 && question.answers.every((answer) => answer.label));
  const targetsValid = value.mode === 'score' ? value.questions.every((question) => question.answers.every((answer) => answer.scores.some((score) => value.results.some((result) => result.id === score.resultId)))) : value.questions.every((question) => question.answers.every((answer) => Boolean(answer.resultId || answer.nextQuestionId)));
  return <AdvancedFrame type="guidedChoice" checks={[{ label: 'Überschrift gesetzt', ok: Boolean(value.headline.trim()) }, { label: '2 bis 6 vollständige Fragen', ok: value.questions.length >= 2 && value.questions.length <= 6 && validAnswers }, { label: 'Mindestens 2 Ergebnisse', ok: value.results.length >= 2 && value.results.every((result) => result.title) }, { label: 'Alle Antworten haben ein Ziel', ok: targetsValid }]}><CommonAdvancedFields value={value} onPatch={(patch) => setValue({ ...value, ...patch })} /><EditorGroup title="2. Logik"><SelectField label="Entscheidungsmodus" value={value.mode} onChange={(mode) => setValue({ ...value, mode })} options={[{ value: 'score', label: 'Score · einfach und empfohlen' }, { value: 'branch', label: 'Branch · freie Verzweigungen' }]} /><p className="rounded-lg bg-blue-50 p-3 text-xs leading-5 text-blue-900">{value.mode === 'score' ? 'Jede Antwort vergibt Punkte. Bei Gleichstand gewinnt immer das zuerst angelegte Ergebnis.' : 'Jede Antwort führt direkt zu einer nächsten Frage oder zu einem Ergebnis. Die Qualitätsprüfung erkennt fehlende Ziele, Zyklen und Sackgassen.'}</p><TextField label="Text für Neustart" value={value.restartLabel} onChange={(restartLabel) => setValue({ ...value, restartLabel })} /></EditorGroup><EditorGroup title="3. Ergebnisse" description="Ergebnisse zuerst anlegen, damit sie bei den Antworten auswählbar sind.">{value.results.map((result, index) => <ItemPanel key={result.id} image={result.image} label={`${index + 1} · ${result.title || 'Neues Ergebnis'}`}><div className="mb-3 flex justify-end"><ReorderButtons index={index} length={value.results.length} onMove={(from, to) => setValue({ ...value, results: moveItem(value.results, from, to) })} onRemove={() => setValue({ ...value, results: value.results.filter((_, itemIndex) => itemIndex !== index) })} /></div><ImageUploadField label="Ergebnisbild (optional)" value={result.image} onChange={(image) => updateResult(index, { image })} /><div className="mt-3"><TextField label="Titel" value={result.title} onChange={(title) => updateResult(index, { title })} /><div className="mt-3"><TextField label="Erklärung" value={result.text} onChange={(text) => updateResult(index, { text })} multiline /></div></div><div className="mt-3 rounded-lg border border-zinc-200 p-3"><p className="text-xs font-bold text-zinc-700">Merkmale</p>{result.features.map((feature, featureIndex) => <div key={featureIndex} className="mt-2 flex gap-2"><input value={feature} onChange={(event) => updateResult(index, { features: result.features.map((entry, nestedIndex) => nestedIndex === featureIndex ? event.target.value : entry) })} className="admin-input flex-1" aria-label={`Merkmal ${featureIndex + 1}`} /><button type="button" onClick={() => updateResult(index, { features: result.features.filter((_, nestedIndex) => nestedIndex !== featureIndex) })} className="rounded-lg px-2 text-red-500 hover:bg-red-50" aria-label="Merkmal entfernen"><Trash2 size={14} /></button></div>)}<button type="button" onClick={() => updateResult(index, { features: [...result.features, ''] })} className="mt-2 text-xs font-bold text-violet-700">+ Merkmal hinzufügen</button></div><div className="mt-3"><ButtonField label="Ergebnis-Button" value={result.cta} onChange={(cta) => updateResult(index, { cta })} /></div></ItemPanel>)}<button type="button" onClick={() => setValue({ ...value, results: [...value.results, { id: makeId('result'), title: '', text: '', image: '', features: [], cta: { label: '', href: '' } }] })} className="text-sm font-semibold text-violet-700">+ Ergebnis hinzufügen</button></EditorGroup><EditorGroup title="4. Fragen und Antworten" description="IDs werden stabil erzeugt. Du arbeitest nur mit verständlichen Auswahllisten.">{value.questions.map((question, questionIndex) => <ItemPanel key={question.id} label={`${questionIndex + 1} · ${question.label || 'Neue Frage'}`}><div className="mb-3 flex justify-end"><ReorderButtons index={questionIndex} length={value.questions.length} onMove={(from, to) => setValue({ ...value, questions: moveItem(value.questions, from, to) })} onRemove={() => setValue({ ...value, questions: value.questions.filter((_, itemIndex) => itemIndex !== questionIndex) })} /></div><TextField label="Frage" value={question.label} onChange={(label) => updateQuestion(questionIndex, { label })} /><div className="mt-3"><TextField label="Kurze Hilfe (optional)" value={question.description} onChange={(description) => updateQuestion(questionIndex, { description })} multiline /></div><div className="mt-4 space-y-3">{question.answers.map((answer, answerIndex) => <div key={answer.id} className="rounded-lg border border-zinc-200 bg-zinc-50 p-3"><div className="flex items-center justify-between gap-2"><strong className="text-xs text-zinc-700">Antwort {answerIndex + 1}</strong><button type="button" onClick={() => updateQuestion(questionIndex, { answers: question.answers.filter((_, index) => index !== answerIndex) })} className="text-red-500" aria-label="Antwort entfernen"><Trash2 size={14} /></button></div><div className="mt-2 grid gap-2 sm:grid-cols-2"><TextField label="Antwort" value={answer.label} onChange={(label) => updateAnswer(questionIndex, answerIndex, { label })} /><TextField label="Erklärung (optional)" value={answer.description} onChange={(description) => updateAnswer(questionIndex, answerIndex, { description })} /></div>{value.mode === 'score' ? <div className="mt-3 grid gap-2 sm:grid-cols-2">{value.results.map((result) => { const score = answer.scores.find((entry) => entry.resultId === result.id)?.points || 0; return <label key={result.id} className="block text-xs"><span className="font-semibold text-zinc-700">Punkte für {result.title || 'Ergebnis'}</span><select value={score} onChange={(event) => updateAnswer(questionIndex, answerIndex, { scores: [...answer.scores.filter((entry) => entry.resultId !== result.id), { resultId: result.id, points: Number(event.target.value) }] })} className="admin-input mt-1 w-full"><option value="0">0 · neutral</option><option value="1">1 · passend</option><option value="2">2 · sehr passend</option><option value="3">3 · ideal</option></select></label>; })}</div> : <div className="mt-3 grid gap-2 sm:grid-cols-2"><SelectField label="Nächste Frage" value={answer.nextQuestionId} onChange={(nextQuestionId) => updateAnswer(questionIndex, answerIndex, { nextQuestionId, resultId: nextQuestionId ? '' : answer.resultId })} options={[{ value: '', label: 'Keine · direktes Ergebnis' }, ...value.questions.filter((entry) => entry.id !== question.id).map((entry) => ({ value: entry.id, label: entry.label || 'Unbenannte Frage' }))]} /><SelectField label="Oder Ergebnis" value={answer.resultId} onChange={(resultId) => updateAnswer(questionIndex, answerIndex, { resultId, nextQuestionId: resultId ? '' : answer.nextQuestionId })} options={[{ value: '', label: 'Bitte wählen' }, ...value.results.map((entry) => ({ value: entry.id, label: entry.title || 'Unbenanntes Ergebnis' }))]} /></div>}</div>)}<button type="button" disabled={question.answers.length >= 4} onClick={() => updateQuestion(questionIndex, { answers: [...question.answers, { id: makeId('answer'), label: '', description: '', scores: [], nextQuestionId: '', resultId: '' }] })} className="text-xs font-bold text-violet-700 disabled:opacity-40">+ Antwort hinzufügen</button></div></ItemPanel>)}<button type="button" disabled={value.questions.length >= 6} onClick={() => setValue({ ...value, questions: [...value.questions, { id: makeId('question'), label: '', description: '', answers: [{ id: makeId('answer'), label: '', description: '', scores: [], nextQuestionId: '', resultId: '' }, { id: makeId('answer'), label: '', description: '', scores: [], nextQuestionId: '', resultId: '' }] }] })} className="text-sm font-semibold text-violet-700 disabled:opacity-40">+ Frage hinzufügen</button></EditorGroup><EditorGroup title="5. Testen" defaultOpen={false}><GuidedChoiceTest mode={value.mode} questions={value.questions} results={value.results} /></EditorGroup></AdvancedFrame>;
}

type TimeScene = { id: string; time: string; label: string; title: string; text: string; image: string; tint: string };
function DayToNightEditor({ data, onChange }: EditorProps) {
  const incoming = Array.isArray(data.scenes) ? data.scenes as Array<Partial<TimeScene>> : [];
  const [value, setValue] = useState({ badge: String(data.badge || ''), headline: String(data.headline || ''), subline: String(data.subline || ''), cta: (data.cta as { label: string; href: string }) || { label: '', href: '' }, scenes: incoming.map((item) => ({ id: item.id || makeId('scene'), time: item.time || '', label: item.label || '', title: item.title || '', text: item.text || '', image: item.image || '', tint: item.tint || '#24365f' })) });
  useReport(value, onChange);
  const update = (index: number, patch: Partial<TimeScene>) => setValue((current) => ({ ...current, scenes: current.scenes.map((item, itemIndex) => itemIndex === index ? { ...item, ...patch } : item) }));
  return <AdvancedFrame type="dayToNight" checks={[{ label: 'Überschrift gesetzt', ok: Boolean(value.headline.trim()) }, { label: '2 bis 4 Szenen', ok: value.scenes.length >= 2 && value.scenes.length <= 4 }, { label: 'Alle Szenen benannt und bebildert', ok: value.scenes.length > 0 && value.scenes.every((item) => item.time && item.title && item.image) }]}><CommonAdvancedFields value={value} onPatch={(patch) => setValue({ ...value, ...patch })} /><EditorGroup title="2. Tageszeiten" description="Dasselbe Bild darf mehrfach mit unterschiedlichen Tints verwendet werden."><BulkImageActions label="Bilder als Szenen hinzufügen" onSelect={(images) => setValue((current) => ({ ...current, scenes: [...current.scenes, ...images.map((image, index) => ({ id: makeId('scene'), time: `${String(8 + index * 4).padStart(2, '0')}:00`, label: image.alt, title: image.alt, text: '', image: image.src, tint: ['#e7a85f', '#6b83a8', '#28375c', '#171b2c'][index % 4] }))].slice(0, 4) }))} />{value.scenes.map((item, index) => <ItemPanel key={item.id} image={item.image} label={`${item.time || '--:--'} · ${item.title || 'Neue Szene'}`}><div className="mb-3 flex justify-end"><ReorderButtons index={index} length={value.scenes.length} onMove={(from, to) => setValue({ ...value, scenes: moveItem(value.scenes, from, to) })} onRemove={() => setValue({ ...value, scenes: value.scenes.filter((_, itemIndex) => itemIndex !== index) })} /></div><ImageUploadField label="Szenenbild" value={item.image} onChange={(image) => update(index, { image })} /><div className="mt-3 grid gap-3 sm:grid-cols-2"><TextField label="Uhrzeit" value={item.time} onChange={(time) => update(index, { time })} /><TextField label="Stimmungslabel" value={item.label} onChange={(label) => update(index, { label })} /><TextField label="Titel" value={item.title} onChange={(title) => update(index, { title })} /><label className="block text-sm"><span className="text-xs font-semibold text-zinc-700">Atmosphären-Tint</span><input type="color" value={item.tint} onChange={(event) => update(index, { tint: event.target.value })} className="mt-1 h-10 w-full rounded-lg border border-zinc-200 bg-white p-1" /></label></div><div className="mt-3"><TextField label="Kurztext" value={item.text} onChange={(text) => update(index, { text })} multiline /></div></ItemPanel>)}<button type="button" disabled={value.scenes.length >= 4} onClick={() => setValue({ ...value, scenes: [...value.scenes, { id: makeId('scene'), time: '', label: '', title: '', text: '', image: '', tint: '#24365f' }] })} className="text-sm font-semibold text-violet-700 disabled:opacity-40">+ Szene hinzufügen</button></EditorGroup><EditorGroup title="3. Abschluss"><ButtonField label="Button (optional)" value={value.cta} onChange={(cta) => setValue({ ...value, cta })} /></EditorGroup></AdvancedFrame>;
}

type BlueprintNode = { id: string; title: string; text: string; icon: string; image: string; metric: string };
function LivingBlueprintEditor({ data, onChange }: EditorProps) {
  const incoming = Array.isArray(data.nodes) ? data.nodes as Array<Partial<BlueprintNode>> : [];
  const [value, setValue] = useState({ badge: String(data.badge || ''), headline: String(data.headline || ''), subline: String(data.subline || ''), layout: String(data.layout || 'flow'), cta: (data.cta as { label: string; href: string }) || { label: '', href: '' }, nodes: incoming.map((item) => ({ id: item.id || makeId('node'), title: item.title || '', text: item.text || '', icon: item.icon || '', image: item.image || '', metric: item.metric || '' })) });
  useReport(value, onChange);
  const update = (index: number, patch: Partial<BlueprintNode>) => setValue((current) => ({ ...current, nodes: current.nodes.map((item, itemIndex) => itemIndex === index ? { ...item, ...patch } : item) }));
  return <AdvancedFrame type="livingBlueprint" checks={[{ label: 'Überschrift gesetzt', ok: Boolean(value.headline.trim()) }, { label: '3 bis 8 Knoten', ok: value.nodes.length >= 3 && value.nodes.length <= 8 }, { label: 'Alle Knoten benannt', ok: value.nodes.length > 0 && value.nodes.every((item) => item.title.trim()) }]}><CommonAdvancedFields value={value} onPatch={(patch) => setValue({ ...value, ...patch })} /><EditorGroup title="2. Bauplan"><SelectField label="Layout-Preset" value={value.layout} onChange={(layout) => setValue({ ...value, layout })} options={[{ value: 'flow', label: 'Fluss' }, { value: 'radial', label: 'Radial' }, { value: 'blueprint', label: 'Bauplan' }]} /><p className="rounded-lg bg-blue-50 p-3 text-xs leading-5 text-blue-900">Positionen und Verbindungslinien erzeugt Flamingo automatisch. Du brauchst keine Koordinaten oder SVG-Datei.</p></EditorGroup><EditorGroup title="3. Knoten"><BulkImageActions label="Bilder als Knoten hinzufügen" onSelect={(images) => setValue((current) => ({ ...current, nodes: [...current.nodes, ...images.map((image) => ({ id: makeId('node'), title: image.alt, text: '', icon: '', image: image.src, metric: '' }))].slice(0, 8) }))} />{value.nodes.map((item, index) => <ItemPanel key={item.id} image={item.image} label={`${index + 1} · ${item.title || 'Neuer Knoten'}`}><div className="mb-3 flex justify-end"><ReorderButtons index={index} length={value.nodes.length} onMove={(from, to) => setValue({ ...value, nodes: moveItem(value.nodes, from, to) })} onRemove={() => setValue({ ...value, nodes: value.nodes.filter((_, itemIndex) => itemIndex !== index) })} /></div><ImageUploadField label="Bild (optional)" value={item.image} onChange={(image) => update(index, { image })} /><div className="mt-3 grid gap-3 sm:grid-cols-2"><TextField label="Titel" value={item.title} onChange={(title) => update(index, { title })} /><TextField label="Kennzahl (optional)" value={item.metric} onChange={(metric) => update(index, { metric })} /></div><div className="mt-3"><TextField label="Erklärung" value={item.text} onChange={(text) => update(index, { text })} multiline /></div></ItemPanel>)}<button type="button" disabled={value.nodes.length >= 8} onClick={() => setValue({ ...value, nodes: [...value.nodes, { id: makeId('node'), title: '', text: '', icon: '', image: '', metric: '' }] })} className="text-sm font-semibold text-violet-700 disabled:opacity-40">+ Knoten hinzufügen</button></EditorGroup><EditorGroup title="4. Abschluss"><ButtonField label="Button (optional)" value={value.cta} onChange={(cta) => setValue({ ...value, cta })} /></EditorGroup></AdvancedFrame>;
}

type MaterialAtelierItem = { id: string; kicker: string; title: string; text: string; image: string; href: string; meta: string[] };
function MaterialAtelierEditor({ data, onChange }: EditorProps) {
  const incoming = Array.isArray(data.items) ? data.items as Array<Partial<MaterialAtelierItem>> : [];
  const [value, setValue] = useState({
    badge: String(data.badge || ''),
    headline: String(data.headline || ''),
    subline: String(data.subline || ''),
    preset: String(data.preset || 'architectural'),
    cta: (data.cta as { label: string; href: string }) || { label: '', href: '' },
    items: incoming.map((item) => ({
      id: item.id || makeId('atelier'),
      kicker: item.kicker || '',
      title: item.title || '',
      text: item.text || '',
      image: item.image || '',
      href: item.href || '',
      meta: Array.isArray(item.meta) ? item.meta.filter((entry): entry is string => typeof entry === 'string') : [],
    })),
  });
  useReport(value, onChange);
  const update = (index: number, patch: Partial<MaterialAtelierItem>) => setValue((current) => ({ ...current, items: current.items.map((item, itemIndex) => itemIndex === index ? { ...item, ...patch } : item) }));
  return <AdvancedFrame type="materialAtelier" checks={[{ label: 'Überschrift gesetzt', ok: Boolean(value.headline.trim()) }, { label: '3 bis 8 Positionen', ok: value.items.length >= 3 && value.items.length <= 8 }, { label: 'Alle Positionen mit Titel und Bild', ok: value.items.length > 0 && value.items.every((item) => item.title.trim() && item.image) }]}>
    <CommonAdvancedFields value={value} onPatch={(patch) => setValue({ ...value, ...patch })} />
    <EditorGroup title="2. Atmosphäre" description="Das Preset verändert Rhythmus und Bewegung, nicht Ihre globalen Farben."><SelectField label="Darstellung" value={value.preset} onChange={(preset) => setValue({ ...value, preset })} options={[{ value: 'architectural', label: 'Architektonisch · präzise' }, { value: 'quiet', label: 'Ruhig · zurückhaltend' }, { value: 'editorial', label: 'Editorial · bildstark' }]} /></EditorGroup>
    <EditorGroup title="3. Positionen" description="Reihenfolge und Auswahlsteuerung entstehen automatisch aus dieser Liste.">
      <BulkImageActions label="Bilder als Positionen hinzufügen" onSelect={(images) => setValue((current) => ({ ...current, items: [...current.items, ...images.map((image) => ({ id: makeId('atelier'), kicker: '', title: image.alt, text: '', image: image.src, href: '', meta: [] }))].slice(0, 8) }))} />
      {value.items.map((item, index) => <ItemPanel key={item.id} image={item.image} label={`${String(index + 1).padStart(2, '0')} · ${item.title || 'Neue Position'}`}><div className="mb-3 flex justify-end"><ReorderButtons index={index} length={value.items.length} onMove={(from, to) => setValue({ ...value, items: moveItem(value.items, from, to) })} onRemove={() => setValue({ ...value, items: value.items.filter((_, itemIndex) => itemIndex !== index) })} /></div><ImageUploadField label="Dominantes Bild" value={item.image} onChange={(image) => update(index, { image })} /><div className="mt-3 grid gap-3 sm:grid-cols-2"><TextField label="Index-Dachzeile" value={item.kicker} onChange={(kicker) => update(index, { kicker })} placeholder="Naturstein · 01" /><TextField label="Titel" value={item.title} onChange={(title) => update(index, { title })} /><DetailLinkField label="Detail-Link (optional)" value={item.href} onChange={(href) => update(index, { href })} /></div><div className="mt-3"><TextField label="Kurze Einordnung" value={item.text} onChange={(text) => update(index, { text })} multiline /></div><div className="mt-4 rounded-lg border border-zinc-200 bg-zinc-50 p-3"><p className="text-xs font-bold text-zinc-700">Meta-Angaben <span className="font-normal text-zinc-500">(maximal 5)</span></p>{item.meta.map((entry, metaIndex) => <div key={`${item.id}-meta-${metaIndex}`} className="mt-2 flex gap-2"><input value={entry} onChange={(event) => update(index, { meta: item.meta.map((value, nestedIndex) => nestedIndex === metaIndex ? event.target.value : value) })} className="admin-input flex-1" placeholder="z. B. gebürstet" aria-label={`Meta-Angabe ${metaIndex + 1}`} /><button type="button" onClick={() => update(index, { meta: item.meta.filter((_, nestedIndex) => nestedIndex !== metaIndex) })} className="grid h-10 w-10 place-items-center rounded-lg text-red-500 hover:bg-red-50" aria-label="Meta-Angabe entfernen"><Trash2 size={14} /></button></div>)}<button type="button" disabled={item.meta.length >= 5} onClick={() => update(index, { meta: [...item.meta, ''] })} className="mt-2 text-xs font-bold text-violet-700 disabled:opacity-40">+ Meta-Angabe hinzufügen</button></div></ItemPanel>)}
      <button type="button" disabled={value.items.length >= 8} onClick={() => setValue({ ...value, items: [...value.items, { id: makeId('atelier'), kicker: '', title: '', text: '', image: '', href: '', meta: [] }] })} className="text-sm font-semibold text-violet-700 disabled:opacity-40">+ Position hinzufügen</button>
    </EditorGroup>
    <EditorGroup title="4. Abschluss"><ButtonField label="Section-Button (optional)" value={value.cta} onChange={(cta) => setValue({ ...value, cta })} /></EditorGroup>
  </AdvancedFrame>;
}

type EditorialFact = { id: string; value: string; label: string };
type EditorialItem = { id: string; kicker: string; title: string; text: string; image: string; href: string; ctaLabel: string; facts: EditorialFact[] };
function EditorialCardMorphEditor({ data, onChange }: EditorProps) {
  const incoming = Array.isArray(data.items) ? data.items as Array<Partial<EditorialItem>> : [];
  const [value, setValue] = useState({ badge: String(data.badge || ''), headline: String(data.headline || ''), subline: String(data.subline || ''), layout: String(data.layout || 'stack'), items: incoming.map((item) => ({ id: item.id || makeId('case'), kicker: item.kicker || '', title: item.title || '', text: item.text || '', image: item.image || '', href: item.href || '', ctaLabel: item.ctaLabel || '', facts: (Array.isArray(item.facts) ? item.facts : []).map((fact) => ({ id: fact.id || makeId('fact'), value: fact.value || '', label: fact.label || '' })) })) });
  useReport(value, onChange);
  const update = (index: number, patch: Partial<EditorialItem>) => setValue((current) => ({ ...current, items: current.items.map((item, itemIndex) => itemIndex === index ? { ...item, ...patch } : item) }));
  return <AdvancedFrame type="editorialCardMorph" checks={[{ label: 'Überschrift gesetzt', ok: Boolean(value.headline.trim()) }, { label: '3 bis 8 Cases', ok: value.items.length >= 3 && value.items.length <= 8 }, { label: 'Alle Cases mit Titel und Bild', ok: value.items.length > 0 && value.items.every((item) => item.title && item.image) }]}><CommonAdvancedFields value={value} onPatch={(patch) => setValue({ ...value, ...patch })} /><EditorGroup title="2. Darstellung"><SelectField label="Layout" value={value.layout} onChange={(layout) => setValue({ ...value, layout })} options={[{ value: 'stack', label: 'Komponierter Stapel' }, { value: 'rail', label: 'Horizontale Schiene' }]} /></EditorGroup><EditorGroup title="3. Cases oder Leistungen" description="Kann später über die bestehende Collection-Injektion auch mit Collection-Items gespeist werden."><BulkImageActions label="Bilder als neue Cases hinzufügen" onSelect={(images) => setValue((current) => ({ ...current, items: [...current.items, ...images.map((image) => ({ id: makeId('case'), kicker: 'Projekt', title: image.alt, text: '', image: image.src, href: '', ctaLabel: '', facts: [] }))].slice(0, 8) }))} />{value.items.map((item, index) => <ItemPanel key={item.id} image={item.image} label={`${index + 1} · ${item.title || 'Neuer Case'}`}><div className="mb-3 flex justify-end"><ReorderButtons index={index} length={value.items.length} onMove={(from, to) => setValue({ ...value, items: moveItem(value.items, from, to) })} onRemove={() => setValue({ ...value, items: value.items.filter((_, itemIndex) => itemIndex !== index) })} /></div><ImageUploadField label="Titelbild" value={item.image} onChange={(image) => update(index, { image })} /><div className="mt-3 grid gap-3 sm:grid-cols-2"><TextField label="Dachzeile" value={item.kicker} onChange={(kicker) => update(index, { kicker })} /><TextField label="Titel" value={item.title} onChange={(title) => update(index, { title })} /><DetailLinkField label="Detail-Link (optional)" value={item.href} onChange={(href) => update(index, { href })} /><TextField label="Button-Text" value={item.ctaLabel} onChange={(ctaLabel) => update(index, { ctaLabel })} /></div><div className="mt-3"><TextField label="Editorialer Kurztext" value={item.text} onChange={(text) => update(index, { text })} multiline /></div><div className="mt-4 rounded-lg border border-zinc-200 p-3"><p className="text-xs font-bold text-zinc-700">Fakten (maximal 4)</p>{item.facts.map((fact, factIndex) => <div key={fact.id} className="mt-2 grid grid-cols-[1fr_1.5fr_auto] gap-2"><input value={fact.value} onChange={(event) => update(index, { facts: item.facts.map((entry, nestedIndex) => nestedIndex === factIndex ? { ...entry, value: event.target.value } : entry) })} className="admin-input" placeholder="38 %" aria-label="Faktwert" /><input value={fact.label} onChange={(event) => update(index, { facts: item.facts.map((entry, nestedIndex) => nestedIndex === factIndex ? { ...entry, label: event.target.value } : entry) })} className="admin-input" placeholder="mehr Anfragen" aria-label="Faktlabel" /><button type="button" onClick={() => update(index, { facts: item.facts.filter((_, nestedIndex) => nestedIndex !== factIndex) })} className="rounded-lg px-2 text-red-500" aria-label="Fakt entfernen"><Trash2 size={14} /></button></div>)}<button type="button" disabled={item.facts.length >= 4} onClick={() => update(index, { facts: [...item.facts, { id: makeId('fact'), value: '', label: '' }] })} className="mt-2 text-xs font-bold text-violet-700 disabled:opacity-40">+ Fakt hinzufügen</button></div></ItemPanel>)}<button type="button" disabled={value.items.length >= 8} onClick={() => setValue({ ...value, items: [...value.items, { id: makeId('case'), kicker: '', title: '', text: '', image: '', href: '', ctaLabel: '', facts: [] }] })} className="text-sm font-semibold text-violet-700 disabled:opacity-40">+ Case hinzufügen</button></EditorGroup></AdvancedFrame>;
}
